  const vm = await drill.waitFor(run, { state: "Working" });
  await drill.fis("terminate-instance", { target: vm.instanceId }); // an AWS FIS experiment template
  await drill.waitFor(run, { state: "Working", notVm: vm.instanceId, withinMs: 10 * MINUTES });
