// Every trigger starts runs through this one function: the run is named after the thing, and a repeat joins it.
import { WorkflowIdConflictPolicy } from '@temporalio/client';

export const startRun = (client, agent, thing, wf, ...args) =>
  client.workflow.start(wf, {
    workflowId: `${agent}:${thing}`,
    taskQueue: `ai-agents-${agent}`,
    workflowIdConflictPolicy: WorkflowIdConflictPolicy.USE_EXISTING,
    args,
  });
