cat > activities.mjs <<'EOF'
// Stand-ins for the VM pool, Slack and Jira. Each one appends what it did to events.jsonl, which the drills read,
// and faults.json is the drill-only switch that makes VMs die (the platform uses AWS FIS for that).
import { appendFile, readFile, writeFile } from 'node:fs/promises';
import { ApplicationFailure, sleep } from '@temporalio/activity';

const record = (event) => appendFile('events.jsonl', JSON.stringify({ at: Date.now(), ...event }) + '\n');
const faults = async () => JSON.parse(await readFile('faults.json', 'utf8').catch(() => '{}'));
let vms = 0;

export const claimVm = async (t, size) => {
  const vm = `i-0${String(++vms).padStart(3, '0')}`;
  await record({ key: t.key, kind: 'vm', action: 'claimed', vm, size });
  return vm;
};

export const workOnVm = async (t, vm, task) => {
  await sleep(500);
  const f = await faults();
  if (f[t.key]?.vmDies > 0) { // the drill asked for this VM to die
    await writeFile('faults.json', JSON.stringify({ ...f, [t.key]: { vmDies: f[t.key].vmDies - 1 } }) + '\n');
    await record({ key: t.key, kind: 'vm', action: 'died', vm });
    throw ApplicationFailure.create({ type: 'SandboxDead', message: `${vm} stopped sending heartbeats`, nonRetryable: true });
  }
  return `${task} done on ${vm}`;
};

export const releaseVm = async (t, vm) => record({ key: t.key, kind: 'vm', action: 'released', vm });
export const notify = async (t, text) => record({ key: t.key, kind: 'slack', text });
export const handBack = async (t, why) => record({ key: t.key, kind: 'jira', assignee: t.requester, why });
EOF
cat > workflows.mjs <<'EOF'
// Nova's run, small but with the real failure rules: one reminder then hand back, Stop always wins,
// a dead VM is replaced once, and a second lost VM stops the run and tells a person.
import {
  ActivityFailure, ApplicationFailure, CancellationScope, condition, defineQuery, defineSignal, proxyActivities, setHandler,
} from '@temporalio/workflow';

const act = proxyActivities({ startToCloseTimeout: '1 minute' });

export const decidePlan = defineSignal('decidePlan');
export const stop = defineSignal('stop');
export const statusQuery = defineQuery('status');

const WAITS = { plan: [1, 3], question: [1, 2] }; // days
const dayMs = (t) => (t.drill ? 2_000 : 24 * 60 * 60 * 1000); // on a drill ticket one "day" is 2 seconds

const waitForPerson = async (run, what, done, t) => {
  const [remind, handBackAt] = WAITS[what].map((d) => d * dayMs(t));
  const over = () => done() || run.stoppedBy !== undefined; // Stop always ends the wait
  if (await condition(over, remind)) return !run.stoppedBy;
  await act.notify(t, `@${t.requester}, the plan is still waiting for your decision.`);
  if (await condition(over, handBackAt - remind)) return !run.stoppedBy;
  await act.handBack(t, 'Nobody decided on the plan in 3 days.');
  return false;
};

const inSandbox = async (run, t, size, task) => {
  for (;;) {
    const vm = await act.claimVm(t, size);
    try {
      return await act.workOnVm(t, vm, task);
    } catch (err) {
      if (!(err instanceof ActivityFailure && err.cause instanceof ApplicationFailure && err.cause.type === 'SandboxDead')) throw err;
      run.lostVms += 1;
      if (run.lostVms >= 2) {
        await act.notify(t, 'This ticket lost two VMs in a row, so I stopped. The branch and my notes are saved.');
        await act.handBack(t, 'Lost two VMs in a row.');
        return undefined;
      }
    } finally {
      await CancellationScope.nonCancellable(() => act.releaseVm(t, vm)); // every VM is released, dead ones too
    }
  }
};

export async function ticketToPr(t) {
  const run = { status: 'Planning', stoppedBy: undefined, lostVms: 0 };
  let decision;
  setHandler(statusQuery, () => run.status);
  setHandler(decidePlan, (d) => { decision = d; });
  setHandler(stop, (by) => { run.stoppedBy = by; });

  if (!(await inSandbox(run, t, 'lite', 'plan'))) return (run.status = 'Needs a person');
  run.status = 'Awaiting approval';
  if (!(await waitForPerson(run, 'plan', () => decision !== undefined, t))) {
    if (!run.stoppedBy) return (run.status = 'Parked');
    await act.handBack(t, `Stopped by ${run.stoppedBy}. The branch and notes are kept.`);
    return (run.status = `Stopped by ${run.stoppedBy}`);
  }
  run.status = 'Working';
  if (!(await inSandbox(run, t, 'full', 'build'))) return (run.status = 'Needs a person');
  await act.handBack(t, 'Draft PR is ready for review.');
  return (run.status = 'PR open');
}
