// The drill kit's helper: start a drill ticket, cause a fault, wait for a state, read what the platform did.
import { readFileSync, writeFileSync } from 'node:fs';
import { connect } from '../connect.mjs';
import { startRun } from '../start-run.mjs';

export const client = await connect();
const handle = (key) => client.workflow.getHandle(`nova:${key}`);
const startedAt = {};

export const drill = {
  // A fresh run for a drill ticket: drill tickets use minutes, here seconds, instead of days.
  async startTicket(key) {
    await handle(key).terminate('drill reset').catch(() => {}); // a leftover from an earlier drill
    startedAt[key] = Date.now();
    return drill.trigger(key);
  },
  trigger: (key) => startRun(client, 'nova', key, 'ticketToPr', { key, requester: 'sean', drill: true }),
  fault(key, fault) {
    const all = JSON.parse(readFileSync('faults.json', { encoding: 'utf8', flag: 'a+' }) || '{}');
    writeFileSync('faults.json', JSON.stringify({ ...all, [key]: fault }) + '\n');
  },
  signal: (key, name, arg) => handle(key).signal(name, arg),
  // Asks the run for its status until it is `state`, or fails with the last status it saw.
  async waitFor(key, state, withinMs) {
    const until = Date.now() + withinMs;
    let last;
    while (Date.now() < until) {
      last = await handle(key).query('status').catch(() => last);
      if (last === state) return;
      await new Promise((r) => setTimeout(r, 200));
    }
    throw new Error(`${key} did not reach "${state}" within ${withinMs} ms (last status: ${last})`);
  },
  // What the platform did for this ticket: VMs claimed and released, Slack messages, Jira changes.
  events: (key, kind) => readFileSync('events.jsonl', { encoding: 'utf8', flag: 'a+' }).split('\n').filter(Boolean)
    .map((l) => JSON.parse(l)).filter((e) => e.key === key && e.at >= (startedAt[key] ?? 0) && (!kind || e.kind === kind)),
};
EOF
