// Drills for the people failures. They act on the running platform, so CI's npm test never runs them.
import assert from 'node:assert/strict';
import { after, test } from 'node:test';
import { client, drill } from './drill.mjs';

after(() => client.connection.close());

test('drill: nobody approves the plan, so one reminder, then the ticket goes back', async () => {
  await drill.startTicket('DRILL-1');
  await drill.waitFor('DRILL-1', 'Awaiting approval', 5_000);
  await drill.waitFor('DRILL-1', 'Parked', 10_000); // 3 drill days
  assert.equal(drill.events('DRILL-1', 'slack').length, 1, 'exactly one reminder');
  assert.equal(drill.events('DRILL-1', 'jira').at(-1)?.assignee, 'sean', 'the ticket is back with the requester');
});

test('drill: the same ticket assigned twice gets one run', async () => {
  const first = await drill.startTicket('DRILL-2');
  const second = await drill.trigger('DRILL-2');
  assert.equal(second.firstExecutionRunId, first.firstExecutionRunId);
});

