cat > drills/vm.test.mjs <<'EOF'
// Drills for VM failures. The platform uses AWS FIS to kill real VMs; here faults.json tells a VM to die.
import assert from 'node:assert/strict';
import { after, test } from 'node:test';
import { client, drill } from './drill.mjs';

after(() => client.connection.close());

const claimed = (key) => drill.events(key, 'vm').filter((e) => e.action === 'claimed').length;
const released = (key) => drill.events(key, 'vm').filter((e) => e.action === 'released').length;

test('drill: a VM that dies is replaced, and the run continues', async () => {
  drill.fault('DRILL-4', { vmDies: 1 });
  await drill.startTicket('DRILL-4');
  await drill.waitFor('DRILL-4', 'Awaiting approval', 10_000);
  assert.equal(claimed('DRILL-4'), 2, 'a fresh VM after the dead one');
  assert.equal(released('DRILL-4'), claimed('DRILL-4'), 'no VM is left behind');
});

test('drill: two lost VMs stop the run and tell a person', async () => {
  drill.fault('DRILL-5', { vmDies: 2 });
  await drill.startTicket('DRILL-5');
  await drill.waitFor('DRILL-5', 'Needs a person', 10_000);
  assert.match(drill.events('DRILL-5', 'slack').at(-1)?.text ?? '', /lost two VMs/);
  assert.equal(released('DRILL-5'), 2, 'both dead VMs are released');
});
