test('drill: Stop while the plan waits ends the run at once', async () => {
  await drill.startTicket('DRILL-3');
  await drill.waitFor('DRILL-3', 'Awaiting approval', 5_000);
  await drill.signal('DRILL-3', 'stop', 'sean');
  await drill.waitFor('DRILL-3', 'Stopped by sean', 1_000); // long before the 2-second reminder
  assert.equal(drill.events('DRILL-3', 'slack').length, 0, 'no reminder after a Stop');
  assert.equal(drill.events('DRILL-3', 'jira').at(-1)?.assignee, 'sean', 'the ticket is back with the requester');
});
